UPDATE database_backup backup
SET status = 'RUNNING', started_at = now(), updated_at = now(),
    finished_at = NULL, expires_at = NULL,
    storage_key = NULL, sha256 = NULL, size_bytes = NULL,
    error_summary = NULL
WHERE backup.id = #{backupId}
  AND backup.job_id = #{jobId}
  AND backup.status IN ('QUEUED', 'FAILED')
  AND EXISTS (
      SELECT 1
      FROM admin_job job
      WHERE job.id = #{jobId}
        AND job.status = 'RUNNING'
        AND job.attempt = #{attempt}
        AND job.lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)
  )

UPDATE database_backup backup
SET status = 'FAILED', finished_at = now(),
    expires_at = now() + make_interval(days => retention_days),
    error_summary = #{summary}, updated_at = now()
WHERE backup.id = #{backupId}
  AND backup.job_id = #{jobId}
  AND backup.status IN ('QUEUED', 'RUNNING')
  AND EXISTS (
      SELECT 1
      FROM admin_job job
      WHERE job.id = #{jobId}
        AND job.status = 'RUNNING'
        AND job.attempt = #{attempt}
        AND job.lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)
  )
